 continue\n    \n    # Check for June in first position (columns 1-2)\n    # Pattern: <td>June</td><td>VALUE</td> or <td>June</td><td>VALUE 2/</td>\n    june_match = re.search(r'<td>June</td><td>([\\d.]+)\\s*(?:2/)?</td>', row)\n    if june_match:\n        # This is June from the first year in this row\n        # We need to track which year this corresponds to\n        print(f\"Found June in row, value: {june_match.group(1)}\")\n        print(f\"Row: {row[:200]}\")\n        print()\n\n# Let me parse more systematically\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
